package com.example.tafakkurai.sync

import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.jsonPrimitive

/** One immutable, persisted fact generated by a meaningful user action. */
data class RecordedActivity(
    val id: String,
    val userId: String,
    val feature: String,
    val type: String,
    val entityId: String,
    val occurredAt: Long,
    val localDate: String,
    val timezone: String,
    val source: String,
    val schemaVersion: Int,
    val properties: JsonObject,
)

/** The small domain shape consumed by Today's plan; UI translates [titleKey]. */
data class ActivityPlanProjection(
    val id: String,
    val planKey: String,
    val titleKey: String,
    val titleArgument: String? = null,
    val aspect: String,
    val completed: Boolean,
    val occurredAt: Long,
    val route: String,
)

/**
 * Projects a day's event stream into one row per real intention/activity.
 *
 * The latest event for a key wins. That is what makes an undo (unmark Qur'an, reset
 * dhikr, clear a prayer mark) remove the earlier completed item instead of leaving a
 * stale green check. Sorting is deterministic for replayed/offline events.
 */
internal fun projectTodayActivities(
    events: List<RecordedActivity>,
    localDate: String,
): List<ActivityPlanProjection> {
    val latest = linkedMapOf<String, RecordedActivity>()
    events.asSequence()
        .filter { it.localDate == localDate }
        .sortedWith(compareBy<RecordedActivity> { it.occurredAt }.thenBy { it.id })
        .forEach { event ->
            if (event.feature == "hifz" && event.type == "hifz_cleared") {
                latest.keys.removeAll { it.startsWith("hifz:") }
            } else {
                planKeyOf(event)?.let { latest[it] = event }
            }
        }

    // Source events are keyed narrowly enough that undoing one item cannot erase its
    // siblings. The UI then coalesces those surviving facts into one honest day/surah row.
    // Example: deleting one of three gratitude entries leaves the other two projected;
    // unmarking one ayah leaves the rest of that surah visible.
    return latest.values.mapNotNull(::projectionOf)
        .groupBy { projection -> displayPlanKey(projection, localDate) }
        .mapNotNull { (displayKey, group) ->
            group.maxWithOrNull(compareBy<ActivityPlanProjection> { it.occurredAt }.thenBy { it.id })
                ?.copy(planKey = displayKey)
        }
        .sortedWith(compareBy<ActivityPlanProjection> { it.occurredAt }.thenBy { it.planKey })
}

private fun planKeyOf(event: RecordedActivity): String? = when (event.feature) {
    "gratitude" -> if (event.type in GRATITUDE_PLAN_EVENTS) {
        "gratitude:${event.entityId}"
    } else null
    "hifz" -> if (event.type in HIFZ_PLAN_EVENTS) {
        event.property("surah")?.let { "hifz:$it" }
    } else null
    "quran" -> if (event.type in QURAN_PLAN_EVENTS) event.property("surah")?.let { surah ->
        "quran:$surah:${event.property("ayah") ?: event.entityId}"
    } else null
    // Habit rows are rendered directly by Today, but their immutable completion facts still
    // enter this read model so Balance can count the real category-specific activity.
    "habits" -> if (event.type in HABIT_PLAN_EVENTS) "habit:${event.entityId}" else null
    "dhikr" -> if (event.type in DHIKR_PLAN_EVENTS) {
        "dhikr:${event.property("dhikr_id") ?: event.entityId}"
    } else null
    "adhkar" -> if (event.type == "adhkar_item_toggled") {
        "adhkar:${event.property("category") ?: event.localDate}:${event.entityId}"
    } else null
    "prayer" -> event.property("prayer")?.let { "prayer:$it:${event.localDate}" }
    "sleep" -> if (event.type in SLEEP_PLAN_EVENTS) "sleep:${event.entityId}" else null
    "finance" -> if (event.type in FINANCE_PLAN_EVENTS) "finance:${event.entityId}" else null
    "tasks" -> "task:${event.entityId}"
    "productivity" -> if (event.type in FOCUS_PLAN_EVENTS) "focus:${event.localDate}" else null
    "social", "thoughts" -> event.socialPlanKey()
    // Per-entry key: deleting an older reflection today must not erase another entry's
    // completed plan row. The entity id is stable across create/edit/delete replays.
    "journal", "tafakkur", "reflect" -> "journal:${event.entityId}"
    "flashcards" -> when (event.type) {
        "card_reviewed" -> "flashcards:${event.localDate}"
        "cards_imported" -> "flashcards:${event.entityId}"
        else -> null
    }
    "learn", "learning" -> if (event.type.contains("lesson") || event.type.contains("quiz")) {
        "learning:${event.entityId}"
    } else null
    "sport", "physical" -> if (event.type in SPORT_PLAN_EVENTS) {
        "sport:${event.entityId}"
    } else null
    else -> null
}

private fun projectionOf(event: RecordedActivity): ActivityPlanProjection? {
    val key = planKeyOf(event) ?: return null
    val common = ProjectionSeed(event, key)
    return when (event.feature) {
        "gratitude" -> when (event.type) {
            "entry_created", "entry_updated", "challenge_day_completed" ->
                common.done("today.plan.gratitude", "spiritual", "gratitude")
            "entry_deleted" -> null
            else -> null
        }
        "hifz" -> when (event.type) {
            "ayahs_enrolled" -> common.pending(
                "today.plan.hifz_surah", "educational", "hifz", event.property("surah"),
            )
            "ayah_reviewed" -> common.done(
                "today.plan.hifz_review", "educational", "hifz", event.property("surah"),
            )
            "ayah_removed" -> if ((event.property("remaining")?.toIntOrNull() ?: 0) > 0) {
                common.pending("today.plan.hifz_surah", "educational", "hifz", event.property("surah"))
            } else null
            "surah_removed", "hifz_cleared" -> null
            else -> null
        }
        "quran" -> when (event.type) {
            "surah_started" -> common.pending(
                "today.plan.quran_surah", "spiritual", "quran", event.property("surah"),
            )
            "ayah_marked_read", "ayah_listened" -> common.done(
                "today.plan.quran_surah", "spiritual", "quran", event.property("surah"),
            )
            "ayah_unmarked_read" -> null
            else -> null
        }
        "habits" -> when (event.type) {
            "habit_completed" -> common.done(
                "today.plan.task",
                event.habitAspect(),
                "habits",
                event.property("title"),
            )
            "habit_progressed" -> common.pending(
                "today.plan.task",
                event.habitAspect(),
                "habits",
                event.property("title"),
            )
            "habit_uncompleted", "habit_skipped" -> null
            else -> null
        }
        "dhikr" -> when (event.type) {
            "dhikr_counted" -> common.done("today.plan.dhikr", "spiritual", "dhikr")
            "dhikr_reset" -> null
            else -> null
        }
        "adhkar" -> when (event.type) {
            "adhkar_item_toggled" -> if (event.property("completed") == "true") {
                common.done("today.plan.adhkar", "spiritual", "adhkar")
            } else null
            else -> null
        }
        "prayer" -> when {
            event.type != "prayer_mark_changed" -> null
            // Older clients serialized PrayerMark.NONE as its UI token, "upcoming".
            // Both values mean the source row was deleted and must clear Today's plan.
            event.property("state") == null || event.property("state") in setOf("none", "upcoming") -> null
            else -> common.done("today.plan.prayer", "spiritual", "prayer", event.property("prayer"))
        }
        "sleep" -> when (event.type) {
            "sleep_started", "bedtime_routine_started", "morning_routine_started" ->
                common.pending("today.plan.sleep", "physical", "sleep")
            "sleep_ended", "sleep_detected", "nap_detected", "nap_logged",
            "bedtime_routine_finished", "morning_routine_finished" ->
                common.done("today.plan.sleep", "physical", "sleep")
            "routine_step_completed", "routine_step_uncompleted" ->
                if (event.property("routine_complete") == "true") {
                    common.done("today.plan.sleep", "physical", "sleep")
                } else {
                    common.pending("today.plan.sleep", "physical", "sleep")
                }
            "sleep_session_deleted" -> null
            else -> null
        }
        "finance" -> when (event.type) {
            "expense_recorded", "income_recorded", "budget_set" ->
                common.done("today.plan.finance", "financial", "finance")
            "savings_goal_created" -> event.property("title")?.let { title ->
                common.pending("today.plan.finance_goal", "financial", "finance", title)
            } ?: common.pending("today.plan.finance", "financial", "finance")
            "savings_goal_contribution" -> event.property("title")?.let { title ->
                common.done("today.plan.finance_goal", "financial", "finance", title)
            } ?: common.done("today.plan.finance", "financial", "finance")
            "transaction_deleted", "budget_deleted", "savings_goal_deleted" -> null
            else -> null
        }
        "tasks" -> when (event.type) {
            "task_created" -> common.pending(
                "today.plan.task", event.taskAspect(), "do", event.property("title"),
            )
            "task_completion_changed" -> if (event.property("completed") == "true") {
                common.done("today.plan.task", event.taskAspect(), "do", event.property("title"))
            } else {
                common.pending("today.plan.task", event.taskAspect(), "do", event.property("title"))
            }
            "task_completed" -> common.done(
                "today.plan.task", event.taskAspect(), event.completedTaskRoute(), event.property("title"),
            )
            "task_deleted" -> null
            else -> null
        }
        "productivity" -> when (event.type) {
            "focus_started", "focus_paused" -> common.pending("today.plan.focus", "productivity", "focus")
            "focus_completed" -> common.done("today.plan.focus", "productivity", "focus")
            "focus_reset" -> null
            else -> null
        }
        "social", "thoughts" -> when (event.type) {
            "connection_added" -> common.pending("today.plan.social_pending", "social", "social")
            "circle_joined", "relationship_check_in", "thought_published" ->
                common.done("today.plan.social", "social", "social")
            "circle_left", "connection_deleted" -> null
            else -> null
        }
        "journal", "tafakkur", "reflect" -> when (event.type) {
            "reflection_created", "reflection_updated", "reflection_saved" ->
                common.done("today.plan.journal", "spiritual", "tafakkur")
            "reflection_deleted" -> null
            else -> null
        }
        "flashcards" -> if (event.type == "cards_imported") {
            common.pending(
                "today.plan.flashcards_created", "educational", "learn", event.property("count"),
            )
        } else {
            common.done("today.plan.flashcards", "educational", "learn")
        }
        "learn", "learning" -> when {
            event.type == "quiz_completed" -> {
                val surah = event.property("surah")?.toIntOrNull()?.takeIf { it in 1..114 }
                if (surah != null) {
                    common.done(
                        "today.plan.quiz_surah",
                        "educational",
                        "quran:quiz:$surah",
                        surah.toString(),
                    )
                } else {
                    common.done("today.plan.quiz", "educational", "quran:quizzes")
                }
            }
            event.type.contains("quiz") -> common.done("today.plan.quiz", "educational", "learn")
            event.type.contains("completed") -> common.done("today.plan.learning", "educational", "learn")
            event.type.contains("started") -> common.pending("today.plan.learning", "educational", "learn")
            else -> null
        }
        "sport", "physical" -> when (event.type) {
            "sport_activity_logged", "sport_completed" ->
                common.done("today.plan.sport", "physical", "sport")
            "sport_activity_removed" -> null
            else -> null
        }
        else -> null
    }
}

/** Collapses item-level replay keys into the one row a person acts on. */
private fun displayPlanKey(projection: ActivityPlanProjection, localDate: String): String = when {
    projection.planKey.startsWith("gratitude:") -> "gratitude:$localDate"
    projection.planKey.startsWith("quran:") -> "quran:${projection.titleArgument ?: localDate}"
    projection.planKey.startsWith("dhikr:") -> "dhikr:$localDate"
    projection.planKey.startsWith("adhkar:") ->
        projection.planKey.split(':').take(2).joinToString(":")
    projection.titleKey == "today.plan.quiz_surah" ->
        "learning:quiz:${projection.titleArgument ?: "unknown"}:$localDate"
    projection.planKey.startsWith("journal:") -> "journal:$localDate"
    projection.planKey.startsWith("sleep:") -> "sleep:$localDate"
    else -> projection.planKey
}

private data class ProjectionSeed(val event: RecordedActivity, val key: String) {
    fun done(key: String, aspect: String, route: String, arg: String? = null) =
        value(key, aspect, route, arg, completed = true)

    fun pending(key: String, aspect: String, route: String, arg: String? = null) =
        value(key, aspect, route, arg, completed = false)

    private fun value(key: String, aspect: String, route: String, arg: String?, completed: Boolean) =
        ActivityPlanProjection(
            id = event.id,
            planKey = this.key,
            titleKey = key,
            titleArgument = arg,
            aspect = aspect,
            completed = completed,
            occurredAt = event.occurredAt,
            route = route,
        )
}

private fun RecordedActivity.property(name: String): String? =
    runCatching { properties[name]?.jsonPrimitive?.content }.getOrNull()?.takeIf { it.isNotBlank() }

private fun RecordedActivity.socialPlanKey(): String? = when (type) {
    "circle_joined", "circle_left" -> "social:circle:$entityId"
    "connection_added", "connection_deleted" -> "social:connection:$entityId"
    "relationship_check_in" -> "social:connection:${property("connection_id") ?: entityId}"
    "thought_published" -> "social:post:$entityId"
    else -> null
}

private fun RecordedActivity.taskAspect(): String = when (property("category")) {
    "health", "fitness", "sport" -> "physical"
    "family", "relationships", "social" -> "social"
    "money", "finance" -> "financial"
    "quran", "faith" -> "spiritual"
    "learning", "study" -> "educational"
    else -> "productivity"
}

private fun RecordedActivity.habitAspect(): String = when (property("category")) {
    "islam", "quran", "faith", "spiritual", "mindfulness" -> "spiritual"
    "workout", "health", "fitness", "sleep", "physical" -> "physical"
    "family", "relationships", "social" -> "social"
    "business", "money", "finance", "financial" -> "financial"
    "english", "reading", "learning", "study", "educational" -> "educational"
    else -> "productivity"
}

private fun RecordedActivity.completedTaskRoute(): String = when (taskAspect()) {
    "physical" -> "sport"
    "social" -> "social"
    "educational" -> "learn"
    "financial" -> "finance"
    "spiritual" -> "quran"
    else -> "do"
}

private val FOCUS_PLAN_EVENTS = setOf(
    "focus_started", "focus_paused", "focus_completed", "focus_reset",
)

private val GRATITUDE_PLAN_EVENTS = setOf(
    "entry_created", "entry_updated", "entry_deleted", "challenge_day_completed",
)

private val HIFZ_PLAN_EVENTS = setOf(
    "ayahs_enrolled", "ayah_reviewed", "ayah_removed", "surah_removed",
)

private val QURAN_PLAN_EVENTS = setOf(
    "surah_started", "ayah_marked_read", "ayah_listened", "ayah_unmarked_read",
)

private val HABIT_PLAN_EVENTS = setOf(
    "habit_completed", "habit_progressed", "habit_uncompleted", "habit_skipped",
)

private val DHIKR_PLAN_EVENTS = setOf("dhikr_counted", "dhikr_reset")

private val SLEEP_PLAN_EVENTS = setOf(
    "sleep_started", "sleep_ended", "sleep_detected", "nap_detected", "nap_logged",
    "sleep_session_deleted", "routine_step_completed", "routine_step_uncompleted",
    "bedtime_routine_started", "bedtime_routine_finished",
    "morning_routine_started", "morning_routine_finished",
)

private val FINANCE_PLAN_EVENTS = setOf(
    "expense_recorded",
    "income_recorded",
    "transaction_deleted",
    "budget_set",
    "budget_deleted",
    "savings_goal_created",
    "savings_goal_contribution",
    "savings_goal_deleted",
)

private val SPORT_PLAN_EVENTS = setOf(
    "sport_activity_logged", "sport_activity_removed", "sport_completed",
)
